//! Canonical, synthetic browser fixtures produced from the Rust domain model.
//!
//! This module is feature-gated so production builds do not include fixture
//! generation. The generated bytes are the only source of functional and
//! performance API bodies served by `web/dev/fixture-server.mjs`.

use crate::model::{
    ATLAS_VERSION, Bip110Assessment, Bip110RuleId, Bip110Status, ChainTip, ClassificationProgress,
    ClassificationResult, ClassificationResultState, ClassificationState, MembershipFacts,
    MempoolEntry, MempoolSnapshot, SourceAvailability, SourceSummary, TransactionStructure,
    classifier_catalog,
};
use crate::staged_snapshot::reencode_manifest_for_source;
use crate::staged_snapshot::{EncodedStage, StageKind, encode_staged_snapshot};
use anyhow::{Context, Result, ensure};
use bitcoin::hashes::{Hash, sha256};
use clap::ValueEnum;
use serde::{Deserialize, Serialize};
use serde_json::{Value, json};
use std::collections::BTreeSet;
use std::fs;
use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};

pub const FIXTURE_MANIFEST_VERSION: u64 = 2;
const FUNCTIONAL_SOURCE_COUNT: usize = 3;
const MAX_PERFORMANCE_SOURCES: usize = 4;
const PERFORMANCE_REFERENCE_TIME_MS: u64 = 1_786_000_000_000;
const Q32_SCALE: u64 = 1_u64 << 32;

#[derive(Clone, Copy, Debug, Eq, PartialEq, ValueEnum)]
pub enum FixtureProfile {
    Functional,
    Performance,
}

impl FixtureProfile {
    fn directory_name(self) -> &'static str {
        match self {
            Self::Functional => "functional",
            Self::Performance => "performance",
        }
    }
}

impl std::fmt::Display for FixtureProfile {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str(self.directory_name())
    }
}

#[derive(Clone, Debug)]
pub struct ExportOptions {
    pub profile: FixtureProfile,
    pub output_root: PathBuf,
    pub transaction_count: usize,
    pub source_count: usize,
}

pub fn write_publication_digest_source_cases(
    output_path: &Path,
    transaction_count: usize,
    source_count: usize,
) -> Result<()> {
    #[derive(Serialize)]
    struct SourceCases {
        schema_version: u64,
        cases: Vec<SourceCase>,
    }

    #[derive(Serialize)]
    struct SourceCase {
        name: &'static str,
        availability: &'static str,
        last_poll_started_at_ms: Option<u64>,
        last_error: Option<&'static str>,
        publication_id: String,
    }

    let (sources, _) = performance_sources(
        PERFORMANCE_REFERENCE_TIME_MS,
        transaction_count,
        source_count,
    )
    .context("build publication digest fixture source")?;
    let source = sources
        .first()
        .context("publication digest fixture source is missing")?;
    let bundle = encode_staged_snapshot(&source.summary, &source.snapshot)
        .context("encode publication digest fixture")?;
    let cases = [
        (
            "ready",
            "ready",
            SourceAvailability::Ready,
            Some(1_785_999_990_000),
            None,
        ),
        (
            "stale_retained_failure",
            "stale",
            SourceAvailability::Stale,
            None,
            Some("Bitcoin node RPC is unavailable"),
        ),
    ];
    let cases = cases
        .into_iter()
        .map(
            |(name, availability_label, availability, last_poll_started_at_ms, last_error)| {
                let mut case_source = bundle.manifest.value.source.clone();
                case_source.availability = availability;
                case_source.last_poll_started_at_ms = last_poll_started_at_ms;
                case_source.last_error = last_error.map(str::to_owned);
                let encoded = reencode_manifest_for_source(&bundle.manifest.value, &case_source)
                    .context("re-encode publication digest source case")?;
                Ok(SourceCase {
                    name,
                    availability: availability_label,
                    last_poll_started_at_ms,
                    last_error,
                    publication_id: encoded.value.publication_id,
                })
            },
        )
        .collect::<Result<Vec<_>>>()?;
    let mut encoded = serde_json::to_vec_pretty(&SourceCases {
        schema_version: 2,
        cases,
    })?;
    encoded.push(b'\n');
    if let Some(parent) = output_path.parent() {
        fs::create_dir_all(parent)
            .with_context(|| format!("create fixture directory {}", parent.display()))?;
    }
    fs::write(output_path, encoded)
        .with_context(|| format!("write source digest fixture {}", output_path.display()))?;
    Ok(())
}

