    #[test]
    fn synthetic_distribution_curves_are_fixed_and_bounded() {
        let samples = [0, 1 << 30, 1 << 31, 3 << 30, u32::MAX];
        let vsize_values = samples.map(vsize_fraction);
        let age_values = samples.map(age_fraction);

        assert_eq!(vsize_values[0], 0);
        assert_eq!(age_values[0], 0);
        assert_eq!(vsize_values[2], 966_367_641);
        assert_eq!(age_values[2], 1_503_238_553);
        assert!(vsize_values.windows(2).all(|pair| pair[0] < pair[1]));
        assert!(age_values.windows(2).all(|pair| pair[0] < pair[1]));
        assert!(vsize_values[4] < Q32_SCALE);
        assert!(age_values[4] < Q32_SCALE);
        assert_eq!(synthetic_output_sats(0), 10_000);
        assert_eq!(synthetic_output_sats(1 << 31), 2_560_000);
        assert!(synthetic_output_sats(u32::MAX) < 655_360_000);
    }

    fn temporary_output_root(test_name: &str) -> PathBuf {
        std::env::temp_dir().join(format!(
            "mempool-atlas-{test_name}-{}-{}",
            std::process::id(),
            unix_time_ms().expect("fixture test time")
        ))
    }

    #[test]
    fn functional_export_has_current_manifest_and_all_contract_bodies() {
        let output_root = temporary_output_root("functional-fixtures");
        let manifest = export(ExportOptions {
            profile: FixtureProfile::Functional,
            output_root: output_root.clone(),
            transaction_count: 1,
            source_count: 1,
        })
        .expect("functional fixture export");

        assert_eq!(manifest.manifest_version, FIXTURE_MANIFEST_VERSION);
        assert_eq!(manifest.snapshots.len(), FUNCTIONAL_SOURCE_COUNT);
        let transaction_count = manifest
            .snapshots
            .iter()
            .map(|snapshot| snapshot.transaction_count)
            .sum::<u64>();
        assert!(
            u64::try_from(manifest.transaction_details.len())
                .expect("fixture detail count fits u64")
                > transaction_count * 9 / 10
        );
        assert!(manifest.output_directory.join("manifest.json").is_file());
        assert!(
            manifest
                .output_directory
                .join(&manifest.source_list.body.path)
                .is_file()
        );
        for snapshot in &manifest.snapshots {
            assert!(
                manifest
                    .output_directory
                    .join(&snapshot.manifest.body.path)
                    .is_file()
            );
            assert_eq!(snapshot.stages.len(), classifier_catalog().len() + 3);
            assert!(snapshot.stages.iter().all(|stage| {
                manifest
                    .output_directory
                    .join(&stage.route.body.path)
                    .is_file()
            }));
        }
        assert!(
            manifest
                .transaction_details
                .iter()
                .all(|detail| detail.route.request_path.starts_with("/api/v2/"))
        );
        for detail in &manifest.transaction_details {
            let body = fs::read(manifest.output_directory.join(&detail.route.body.path))
                .expect("read transaction detail fixture");
            assert!(
                !body
                    .windows(br#"\"fixture\":true"#.len())
                    .any(|window| window == br#"\"fixture\":true"#),
                "transaction detail fixtures must contain presentable evidence"
            );
        }
        fs::remove_dir_all(output_root).expect("remove functional fixture test output");
    }

